      "items" : {
        "type" : "number"
      }
    }
  }
}

vars.jsonSchema:
{
  "maxItems" : 6,
  "minItems" : 6,
  "type" : "array",
  "description" : "This parameter contains information on the coordinate range for its Geometries, Features or FeatureCollections. It describes a bounding box for this. The coordinates are given in the decimal degrees unit. The altitude is given in meter. In the following it is described, which value of the array represents which coordinate:\n  - The most southwesterly point: Longitude\n  - The most southwesterly point: Latitude\n  - The most southwesterly point: Altitude\n  - The most northeasterly point: Longitude\n  - The most northeasterly point: Latitude\n  - The most northeasterly point: Altitude\n",
  "example" : [ 8.01234567890123, 49.0123456789012, 154.1, 8.12345678901234, 49.1234567890123, 138.2 ],
  "externalDocs" : {
    "description" : "RFC7946 - The GeoJSON format",
    "url" : "https://tools.ietf.org/html/rfc7946#section-5"
  },
  "items" : {
    "type" : "number"
  }
}

